/**
 * Branches (tenants) of the caller's account.
 *   GET    - owner: all branches of the account; others: their own branches
 *   POST   - owner only, within the plan's branch limit
 *   PUT    - owner only: rename / activate / deactivate
 *   DELETE - owner only: deactivates (data is kept). Permanent deletion is a
 *            support operation and is not exposed through the API.
 *
 * The schema name is generated by the server and never changes.
 */
const express = require("express");
const db = require("../db");
const { authenticate, requireOwner, listAccessibleTenants } = require("../middleware/auth");
const { createTenant } = require("../services/provisioning");

const router = express.Router();
router.use(authenticate());

router.get("/", async (req, res, next) => {
  try {
    const rows = await listAccessibleTenants(req.auth);
    res.json(rows.map(({ id, name, is_active, created_at }) => ({ id, name, is_active, created_at })));
  } catch (err) {
    next(err);
  }
});

router.post("/", requireOwner, async (req, res, next) => {
  try {
    const tenant = await createTenant({ accountId: req.user.accountId, name: req.body?.name });
    res.status(201).json({ id: tenant.id, name: tenant.name, is_active: tenant.is_active, created_at: tenant.created_at });
  } catch (err) {
    if (err.status) return res.status(err.status).json({ message: err.message });
    next(err);
  }
});

router.put("/:id", requireOwner, async (req, res, next) => {
  const name = typeof req.body?.name === "string" ? req.body.name.trim() : null;
  const isActive = typeof req.body?.is_active === "boolean" ? req.body.is_active : null;
  if (name === "") return res.status(400).json({ message: "Name cannot be empty" });

  try {
    if (isActive === false && req.params.id === req.user.tenantId) {
      return res.status(400).json({ message: "Switch to another branch before deactivating this one" });
    }
    if (isActive === true) {
      // Re-activating counts against the plan limit like a new branch.
      const { rows } = await db.query(
        `SELECT p.max_branches,
                (SELECT count(*)::int FROM public.tenants WHERE account_id = $1 AND is_active) AS used,
                (SELECT is_active FROM public.tenants WHERE id = $2 AND account_id = $1) AS current
           FROM public.accounts a JOIN public.plans p ON p.id = a.plan_id WHERE a.id = $1`,
        [req.user.accountId, req.params.id]
      );
      const r = rows[0];
      if (r && r.current === false && r.max_branches != null && r.used >= r.max_branches) {
        return res.status(403).json({ message: `Your plan allows ${r.max_branches} active branch(es)` });
      }
    }

    const { rows } = await db.query(
      `UPDATE public.tenants
          SET name = COALESCE($3, name), is_active = COALESCE($4, is_active)
        WHERE id = $1 AND account_id = $2
        RETURNING id, name, is_active, created_at`,
      [req.params.id, req.user.accountId, name, isActive]
    );
    if (!rows.length) return res.status(404).json({ message: "Branch not found" });
    res.json(rows[0]);
  } catch (err) {
    next(err);
  }
});

router.delete("/:id", requireOwner, async (req, res, next) => {
  try {
    if (req.params.id === req.user.tenantId) {
      return res.status(400).json({ message: "Switch to another branch before removing this one" });
    }
    const { rowCount } = await db.query(
      `UPDATE public.tenants SET is_active = false WHERE id = $1 AND account_id = $2`,
      [req.params.id, req.user.accountId]
    );
    if (!rowCount) return res.status(404).json({ message: "Branch not found" });
    res.status(204).send();
  } catch (err) {
    next(err);
  }
});

module.exports = router;
